import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

/// Maintix full brand logo (name + tagline) as an embedded high quality
/// PNG (base64). Embedding avoids any asset-bundling/path issues and
/// guarantees the exact same logo renders everywhere it's used.
///
/// NOTE: This is ONLY the full "Maintix" wordmark logo. The standalone
/// 'M' app icon/mark used elsewhere in the app is untouched.
const String kMaintixLogoBase64 =
    '';

class MaintixLogo extends StatelessWidget {
  final double? width;
  final double? height;
  final double borderRadius;
  final BoxFit fit;

  const MaintixLogo({
    super.key,
    this.width,
    this.height,
    this.borderRadius = 14,
    this.fit = BoxFit.contain,
  });

  static final Uint8List _bytes = base64Decode(kMaintixLogoBase64);

  @override
  Widget build(BuildContext context) {
    return ClipRRect(
      borderRadius: BorderRadius.circular(borderRadius),
      child: Image.memory(
        _bytes,
        width: width,
        height: height,
        fit: fit,
        filterQuality: FilterQuality.high,
        gaplessPlayback: true,
      ),
    );
  }
}
